package com.rezoxnemesis.videostudio;

import org.json.JSONObject;
import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.function.LongConsumer;

/** Pinned model-file engineering, never artwork or inference. Invoked on an install worker.
 * Tensor payloads are copied from disk in64KiB chunks; only bounded node/type metadata is parsed.
 * The caller's native catalogue must pin BOTH source and deterministic derived SHA256 values.
 */
final class LocalDrawingPlusGraphConverter {
 private static final int CHUNK=65536,METADATA=1024*1024,MAX_EDITS=256;
 private static final long MAX_MODEL=3L*1024*1024*1024;
 private static final String PENULTIMATE="/vision_model/encoder/layers.30/Add_1_output_0";
 private static final String[] LAYERS={"down_blocks.0/attentions.0","down_blocks.0/attentions.1","down_blocks.1/attentions.0","down_blocks.1/attentions.1","down_blocks.2/attentions.0","down_blocks.2/attentions.1","up_blocks.1/attentions.0","up_blocks.1/attentions.1","up_blocks.1/attentions.2","up_blocks.2/attentions.0","up_blocks.2/attentions.1","up_blocks.2/attentions.2","up_blocks.3/attentions.0","up_blocks.3/attentions.1","up_blocks.3/attentions.2","mid_block/attentions.0"};
 private static final int[] INNER={320,320,640,640,1280,1280,1280,1280,1280,640,640,640,320,320,320,1280};
 private static final long[][] RESIDUALS={{1,320,64,64},{1,320,64,64},{1,320,64,64},{1,320,32,32},{1,640,32,32},{1,640,32,32},{1,640,16,16},{1,1280,16,16},{1,1280,16,16},{1,1280,8,8},{1,1280,8,8},{1,1280,8,8},{1,1280,8,8}};
 private LocalDrawingPlusGraphConverter(){}
 static JSONObject convert(String recipe,File source,File target,String sourceSha,String resultSha,LongConsumer progress)throws Exception {
  check();if(!Arrays.asList("clip_penultimate_v1","sd15_ipkv16_v1","sd15_legacy_ipkv_probe_v1").contains(recipe)||sourceSha==null||resultSha==null||!sourceSha.matches("[a-f0-9]{64}")||!resultSha.matches("[a-f0-9]{64}"))throw new IOException("PLUS_CONVERSION_RECIPE_OR_PIN_INVALID");
  if(!source.isFile()||source.length()<1||source.length()>MAX_MODEL||Files.isSymbolicLink(source.toPath())||Files.isSymbolicLink(target.toPath())||source.getCanonicalFile().equals(target.getCanonicalFile()))throw new IOException("PLUS_CONVERSION_PATH_INVALID");
  if(!sourceSha.equals(LocalDrawingModels.hash(source)))throw new IOException("PLUS_CONVERSION_SOURCE_SHA_DIFFERS");
  Plan plan;try(RandomAccessFile input=new RandomAccessFile(source,"r")){plan=recipe.equals("sd15_legacy_ipkv_probe_v1")?legacyAuditPlan(input):plan(input,recipe);}
  File parent=target.getAbsoluteFile().getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("Cannot create private model conversion directory");if(target.exists()&&!target.isFile())throw new IOException("PLUS_CONVERSION_TARGET_INVALID");File temporary=File.createTempFile(".plus_",".onnx",parent);boolean published=false;
  try{
   long written;try(RandomAccessFile input=new RandomAccessFile(source,"r");FileOutputStream output=new FileOutputStream(temporary)){Writer writer=new Writer(output,progress);long position=0;for(Edit edit:plan.edits){if(edit.start<position)throw new IOException("PLUS_CONVERSION_PATCH_OVERLAP");copy(input,writer,position,edit.start-position);writer.write(edit.bytes,0,edit.bytes.length);position=edit.end;}copy(input,writer,position,input.length()-position);output.getFD().sync();written=writer.written;}
   check();String actualSha=LocalDrawingModels.hash(temporary);if(!resultSha.equals(actualSha))throw new IOException("PLUS_CONVERSION_RESULT_SHA_DIFFERS: expected="+resultSha+" actual="+actualSha);check();Files.move(temporary.toPath(),target.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);published=true;
   return new JSONObject().put("recipe",recipe).put("sourceSha256",sourceSha).put("resultSha256",resultSha).put("sourceBytes",source.length()).put("resultBytes",written).put("patchCount",plan.edits.size()).put("prunedNodes",plan.pruned).put("maxCopyChunkBytes",CHUNK).put("maxMetadataBytes",METADATA).put("inferenceExecuted",false);
  }finally{if(!published&&temporary.exists()&&!temporary.delete())temporary.deleteOnExit();}
 }
 /** Private engineering audit: append existing4-token projections as outputs only.
  * It never becomes the installed generation UNet and never changes a source field.
  */
 private static Plan legacyAuditPlan(RandomAccessFile input)throws Exception {
  Field graph=null;long end=input.length();while(input.getFilePointer()<end){check();Field field=field(input,end);if(field.tag==7&&field.wire==2){if(graph!=null)throw new IOException("PLUS_CONVERSION_MULTIPLE_GRAPHS");graph=field;}input.seek(field.end);}if(graph==null)throw new IOException("PLUS_CONVERSION_GRAPH_MISSING");
  Map<String,Value> inputs=new LinkedHashMap<>();Set<String> oldOutputs=new HashSet<>();boolean[][] found=new boolean[16][2];input.seek(graph.payload);
  while(input.getFilePointer()<graph.end){check();Field field=field(input,graph.end);if(field.tag==1&&field.wire==2){Node node=node(payload(input,field,METADATA));for(int i=0;i<16;i++)for(int site=0;site<2;site++){String name=prefix(i)+(site==0?"to_k_ip.0/MatMul":"to_v_ip.0/MatMul");if(!node.name.equals(name))continue;if(found[i][site]||!node.op.equals("MatMul")||!node.outputs.equals(Collections.singletonList(name+"_output_0")))throw new IOException("PLUS_LEGACY_KV_PROJECTION_DIFFERS");found[i][site]=true;}}
   else if(field.tag==11&&field.wire==2){Value value=value(payload(input,field,65536));if(inputs.put(value.name,value)!=null)throw new IOException("PLUS_CONVERSION_DUPLICATE_INPUT");}
   else if(field.tag==12&&field.wire==2){Value value=value(payload(input,field,65536));if(!oldOutputs.add(value.name))throw new IOException("PLUS_LEGACY_KV_OUTPUT_DIFFERS");}
   else if(field.tag==5&&field.wire==2)tensorName(input,field);input.seek(field.end);
  }
  if(inputs.size()!=17||oldOutputs.size()!=1||!oldOutputs.contains("noise_pred"))throw new IOException("PLUS_LEGACY_KV_BASE_CONTRACT_DIFFERS");require(inputs,"sample",1,4,64,64);require(inputs,"timestep",1);require(inputs,"encoder_hidden_states",1,77,768);require(inputs,"image_embeds",1,1,1024);for(int i=0;i<13;i++)require(inputs,residual(i),RESIDUALS[i]);
  ByteArrayOutputStream append=new ByteArrayOutputStream();for(int i=0;i<16;i++)for(int site=0;site<2;site++){if(!found[i][site])throw new IOException("PLUS_LEGACY_KV_PROJECTION_MISSING");append.write(wrap(12,value(prefix(i)+(site==0?"to_k_ip.0/MatMul_output_0":"to_v_ip.0/MatMul_output_0"),10,1,1,4,INNER[i])));}byte[] addition=append.toByteArray();Plan plan=new Plan();plan.edits.add(new Edit(graph.start,graph.payload,concat(varint(58),varint(graph.length+addition.length))));plan.edits.add(new Edit(graph.end,graph.end,addition));return plan;
 }
 private static Plan plan(RandomAccessFile input,String recipe)throws Exception {
  Field graph=null;long length=input.length();while(input.getFilePointer()<length){check();Field field=field(input,length);if(field.tag==7&&field.wire==2){if(graph!=null)throw new IOException("PLUS_CONVERSION_MULTIPLE_GRAPHS");graph=field;}input.seek(field.end);}if(graph==null)throw new IOException("PLUS_CONVERSION_GRAPH_MISSING");
  boolean clip=recipe.equals("clip_penultimate_v1");Plan plan=new Plan();Map<String,Value> inputs=new LinkedHashMap<>();Set<String> outputs=new HashSet<>(),tainted=new HashSet<>(),survivingUses=new HashSet<>();tainted.add("image_embeds");boolean[][] sites=new boolean[16][4];int penultimate=0;ByteArrayOutputStream appended=new ByteArrayOutputStream();
  input.seek(graph.payload);while(input.getFilePointer()<graph.end){check();Field field=field(input,graph.end);
   if(field.tag==1&&field.wire==2){byte[] bytes=payload(input,field,METADATA);Node node=node(bytes);if(clip){if(node.name.equals("/vision_model/encoder/layers.30/Add_1")){if(!node.op.equals("Add")||!node.outputs.equals(Collections.singletonList(PENULTIMATE))||++penultimate!=1)throw new IOException("PLUS_CONVERSION_PENULTIMATE_DIFFERS");}}
    else{int layer=-1,site=-1;for(int i=0;i<16;i++){String prefix=prefix(i);if(node.name.equals(prefix+"to_k_ip.0/MatMul")){layer=i;site=0;break;}if(node.name.equals(prefix+"to_v_ip.0/MatMul")){layer=i;site=1;break;}if(node.name.equals(prefix+"Reshape_4")){layer=i;site=2;break;}if(node.name.equals(prefix+"Reshape_5")){layer=i;site=3;break;}}
     if(layer>=0){if(sites[layer][site])throw new IOException("PLUS_CONVERSION_DUPLICATE_IP_SITE");sites[layer][site]=true;String prefix=prefix(layer);if(site<2){boolean key=site==0;String expected=prefix+(key?"to_k_ip.0/MatMul_output_0":"to_v_ip.0/MatMul_output_0");if(!node.op.equals("MatMul")||!node.outputs.equals(Collections.singletonList(expected)))throw new IOException("PLUS_CONVERSION_IP_PROJECTION_DIFFERS");plan.add(field,wrap(1,kvNode(layer,key)));survivingUses.add((key?"ipk_":"ipv_")+layer);}
      else{String expected=prefix+(site==2?"to_k_ip.0/MatMul_output_0":"to_v_ip.0/MatMul_output_0");if(!node.op.equals("Reshape")||node.inputs.size()!=2||!node.inputs.get(0).equals(expected))throw new IOException("PLUS_CONVERSION_IP_RESHAPE_DIFFERS");plan.add(field,wrap(1,replaceInput(bytes,1,"videostudio_ip_shape_"+layer)));survivingUses.add(expected);}}
     else if(node.name.startsWith("/unet/encoder_hid_proj/")||node.inputs.stream().anyMatch(tainted::contains)){plan.add(field,new byte[0]);tainted.addAll(node.outputs);plan.pruned++;if(tainted.size()>4096||plan.pruned>128)throw new IOException("PLUS_CONVERSION_IMAGE_BRANCH_EXCEEDS_BOUND");}
     else survivingUses.addAll(node.inputs);
    }
   }else if(field.tag==11&&field.wire==2){byte[] bytes=payload(input,field,65536);Value value=value(bytes);if(inputs.put(value.name,value)!=null)throw new IOException("PLUS_CONVERSION_DUPLICATE_INPUT");if(!clip&&value.name.equals("image_embeds"))plan.add(field,new byte[0]);}
   else if(field.tag==12&&field.wire==2){Value value=value(payload(input,field,65536));if(!outputs.add(value.name)||value.name.equals("penultimate_hidden_states"))throw new IOException("PLUS_CONVERSION_OUTPUT_ALREADY_PREPARED");}
   else if(field.tag==5&&field.wire==2){String name=tensorName(input,field);if(name.startsWith("videostudio_ip_shape_"))throw new IOException("PLUS_CONVERSION_SHAPE_NAME_COLLISION");}
   input.seek(field.end);
  }
  if(clip){if(inputs.size()!=1||penultimate!=1)throw new IOException("PLUS_CONVERSION_CLIP_CONTRACT_DIFFERS");require(inputs,"pixel_values",1,3,224,224);appended.write(wrap(1,node("videostudio/penultimate_hidden_states","Identity",new String[]{PENULTIMATE},new String[]{"penultimate_hidden_states"})));appended.write(wrap(12,value("penultimate_hidden_states",10,1,257,1280)));}
  else{
   if(inputs.size()!=17||tainted.contains("noise_pred")||survivingUses.contains("image_embeds")||!outputs.contains("noise_pred"))throw new IOException("PLUS_CONVERSION_UNET_CONTRACT_DIFFERS");require(inputs,"sample",1,4,64,64);require(inputs,"timestep",1);require(inputs,"encoder_hidden_states",1,77,768);require(inputs,"image_embeds",1,1,1024);for(int i=0;i<13;i++)require(inputs,residual(i),RESIDUALS[i]);for(String name:inputs.keySet())if(!name.equals("image_embeds")&&!survivingUses.contains(name))throw new IOException("PLUS_CONVERSION_BACKBONE_INPUT_LOST: "+name);
   for(int i=0;i<16;i++){for(boolean found:sites[i])if(!found)throw new IOException("PLUS_CONVERSION_IP_SITE_MISSING");appended.write(wrap(5,shapeTensor(i)));}for(int i=0;i<16;i++){appended.write(wrap(11,value("ipk_"+i,10,1,INNER[i],16)));appended.write(wrap(11,value("ipv_"+i,10,1,16,INNER[i])));}
  }
  byte[] addition=appended.toByteArray();long graphLength=graph.length+addition.length;for(Edit edit:plan.edits)graphLength+=edit.bytes.length-(edit.end-edit.start);if(graphLength<1||graphLength>MAX_MODEL)throw new IOException("PLUS_CONVERSION_GRAPH_SIZE_INVALID");plan.edits.add(new Edit(graph.start,graph.payload,concat(varint(58),varint(graphLength))));plan.edits.add(new Edit(graph.end,graph.end,addition));plan.edits.sort(Comparator.comparingLong(e->e.start));long last=-1,metadata=0;for(Edit edit:plan.edits){if(edit.start<last)throw new IOException("PLUS_CONVERSION_PATCH_OVERLAP");last=edit.end;metadata+=edit.bytes.length;}if(metadata>4L*METADATA||plan.edits.size()>MAX_EDITS)throw new IOException("PLUS_CONVERSION_METADATA_EXCEEDS_BOUND");return plan;
 }
 private static void require(Map<String,Value> values,String name,long...shape)throws Exception {Value value=values.get(name);if(value==null||value.type!=10||value.shape.size()!=shape.length)throw new IOException("PLUS_CONVERSION_INPUT_DIFFERS: "+name);for(int i=0;i<shape.length;i++){Object dimension=value.shape.get(i);if(i==0&&dimension instanceof String&&dimension.equals("batch"))continue;if(!(dimension instanceof Long)||((Long)dimension)!=shape[i])throw new IOException("PLUS_CONVERSION_INPUT_SHAPE_DIFFERS: "+name);}}
 private static String tensorName(RandomAccessFile input,Field tensor)throws Exception {String name="";input.seek(tensor.payload);while(input.getFilePointer()<tensor.end){Field field=field(input,tensor.end);if(field.tag==8&&field.wire==2)name=new String(payload(input,field,65536),StandardCharsets.UTF_8);if(field.tag==13||field.tag==14&&(field.wire!=0||field.number!=0))throw new IOException("PLUS_CONVERSION_EXTERNAL_TENSOR_UNSUPPORTED");input.seek(field.end);}return name;}
 private static byte[] replaceInput(byte[] bytes,int index,String replacement)throws Exception {ByteArrayOutputStream output=new ByteArrayOutputStream();int input=0;for(Field field:fields(bytes)){if(field.tag==1&&field.wire==2&&input++==index)output.write(text(1,replacement));else output.write(bytes,(int)field.start,(int)(field.end-field.start));}if(input<=index)throw new IOException("PLUS_CONVERSION_INPUT_INDEX_INVALID");return output.toByteArray();}
 private static Node node(byte[] bytes)throws Exception {Node n=new Node();for(Field field:fields(bytes)){if(field.wire!=2)continue;String text;if(field.tag>=1&&field.tag<=4){text=string(bytes,field);if(field.tag==1)n.inputs.add(text);else if(field.tag==2)n.outputs.add(text);else if(field.tag==3)n.name=text;else n.op=text;}}if(n.name.isEmpty()||n.op.isEmpty()||n.inputs.size()>128||n.outputs.size()>128)throw new IOException("PLUS_CONVERSION_NODE_METADATA_INVALID");return n;}
 private static Value value(byte[] bytes)throws Exception {Value v=new Value();for(Field field:fields(bytes)){if(field.tag==1&&field.wire==2)v.name=string(bytes,field);else if(field.tag==2&&field.wire==2)for(Field type:fields(slice(bytes,field)))if(type.tag==1&&type.wire==2){byte[] tensor=slice(slice(bytes,field),type);for(Field descriptor:fields(tensor)){if(descriptor.tag==1&&descriptor.wire==0)v.type=(int)descriptor.number;else if(descriptor.tag==2&&descriptor.wire==2){byte[] shape=slice(tensor,descriptor);for(Field dim:fields(shape))if(dim.tag==1&&dim.wire==2){Object result=null;for(Field component:fields(slice(shape,dim))){if(component.tag==1&&component.wire==0)result=component.number;else if(component.tag==2&&component.wire==2)result=string(slice(shape,dim),component);}v.shape.add(result);}}}}}if(v.name.isEmpty())throw new IOException("PLUS_CONVERSION_VALUE_NAME_MISSING");return v;}
 private static List<Field> fields(byte[] bytes)throws Exception {Memory input=new Memory(bytes);List<Field> out=new ArrayList<>();while(input.position<bytes.length){if(out.size()>=4096)throw new IOException("PLUS_CONVERSION_METADATA_FIELDS_EXCEED_BOUND");out.add(input.field());}return out;}
 private static Field field(RandomAccessFile input,long end)throws Exception {Field f=new Field();f.start=input.getFilePointer();long key=read(input);if(key<=0||key>>>3>Integer.MAX_VALUE)throw new IOException("PLUS_CONVERSION_PROTO_TAG_INVALID");f.tag=(int)(key>>>3);f.wire=(int)(key&7);if(f.wire==0){f.number=read(input);f.payload=input.getFilePointer();f.end=f.payload;}else if(f.wire==2){f.length=read(input);f.payload=input.getFilePointer();if(f.length<0||f.length>end-f.payload)throw new IOException("PLUS_CONVERSION_PROTO_LENGTH_INVALID");f.end=f.payload+f.length;}else if(f.wire==1||f.wire==5){f.payload=input.getFilePointer();f.length=f.wire==1?8:4;f.end=f.payload+f.length;}else throw new IOException("PLUS_CONVERSION_PROTO_WIRE_UNSUPPORTED");if(f.end>end)throw new IOException("PLUS_CONVERSION_PROTO_TRUNCATED");return f;}
 private static long read(RandomAccessFile input)throws Exception {long value=0;for(int shift=0;shift<70;shift+=7){int b=input.read();if(b<0)throw new EOFException("Truncated model metadata");if(shift==63&&(b&254)!=0)throw new IOException("Model varint overflow");value|=(long)(b&127)<<shift;if((b&128)==0)return value;}throw new IOException("Model varint overflow");}
 private static byte[] payload(RandomAccessFile input,Field field,int limit)throws Exception {if(field.length<0||field.length>limit)throw new IOException("PLUS_CONVERSION_METADATA_EXCEEDS_BOUND");byte[] bytes=new byte[(int)field.length];input.seek(field.payload);input.readFully(bytes);return bytes;}
 private static byte[] slice(byte[] bytes,Field f)throws Exception {if(f.wire!=2||f.length>METADATA||f.payload<0||f.end>bytes.length)throw new IOException("Invalid bounded model metadata");return Arrays.copyOfRange(bytes,(int)f.payload,(int)f.end);}
 private static String string(byte[] bytes,Field f)throws Exception {if(f.length>65536)throw new IOException("Model metadata string exceeds bound");return new String(slice(bytes,f),StandardCharsets.UTF_8);}
 private static void copy(RandomAccessFile input,Writer output,long start,long length)throws Exception {if(length<0)throw new IOException("Invalid model splice");input.seek(start);byte[] buffer=new byte[CHUNK];while(length>0){check();int count=(int)Math.min(length,buffer.length);input.readFully(buffer,0,count);output.write(buffer,0,count);length-=count;}}
 private static String prefix(int i){return"/unet/"+LAYERS[i]+"/transformer_blocks.0/attn2/";}
 private static String residual(int i){return i<12?"down_residual_"+i:"mid_residual";}
 private static byte[] kvNode(int i,boolean key)throws Exception {String prefix=prefix(i);if(!key)return node(prefix+"to_v_ip.0/MatMul","Identity",new String[]{"ipv_"+i},new String[]{prefix+"to_v_ip.0/MatMul_output_0"});byte[] attr=concat(text(1,"perm"),number(20,7),wrap(8,concat(varint(0),varint(2),varint(1))));return concat(node(prefix+"to_k_ip.0/MatMul","Transpose",new String[]{"ipk_"+i},new String[]{prefix+"to_k_ip.0/MatMul_output_0"}),wrap(5,attr));}
 private static byte[] shapeTensor(int i)throws Exception {ByteBuffer data=ByteBuffer.allocate(32).order(ByteOrder.LITTLE_ENDIAN);for(long v:new long[]{1,16,8,INNER[i]/8})data.putLong(v);return concat(number(1,4),number(2,7),text(8,"videostudio_ip_shape_"+i),wrap(9,data.array()));}
 private static byte[] node(String name,String op,String[] inputs,String[] outputs)throws Exception {ByteArrayOutputStream bytes=new ByteArrayOutputStream();for(String input:inputs)bytes.write(text(1,input));for(String output:outputs)bytes.write(text(2,output));bytes.write(text(3,name));bytes.write(text(4,op));return bytes.toByteArray();}
 private static byte[] value(String name,int type,long...shape)throws Exception {ByteArrayOutputStream dims=new ByteArrayOutputStream();for(long dimension:shape)dims.write(wrap(1,number(1,dimension)));return concat(text(1,name),wrap(2,wrap(1,concat(number(1,type),wrap(2,dims.toByteArray())))));}
 private static byte[] text(int tag,String text)throws Exception {return wrap(tag,text.getBytes(StandardCharsets.UTF_8));}
 private static byte[] wrap(int tag,byte[] payload)throws Exception {return concat(varint(((long)tag<<3)|2),varint(payload.length),payload);}
 private static byte[] number(int tag,long number)throws Exception {return concat(varint((long)tag<<3),varint(number));}
 private static byte[] varint(long value){ByteArrayOutputStream bytes=new ByteArrayOutputStream();while((value&~127L)!=0){bytes.write((int)(value&127)|128);value>>>=7;}bytes.write((int)value);return bytes.toByteArray();}
 private static byte[] concat(byte[]...arrays)throws Exception {ByteArrayOutputStream bytes=new ByteArrayOutputStream();for(byte[] array:arrays)bytes.write(array);return bytes.toByteArray();}
 private static void check()throws InterruptedException {if(Thread.currentThread().isInterrupted())throw new InterruptedException("Native Plus model conversion cancelled");}
 private static final class Plan{final List<Edit> edits=new ArrayList<>();int pruned;void add(Field field,byte[] bytes)throws Exception {if(edits.size()>=MAX_EDITS)throw new IOException("Too many model conversion patches");edits.add(new Edit(field.start,field.end,bytes));}}
 private static final class Edit{final long start,end;final byte[] bytes;Edit(long s,long e,byte[] b){start=s;end=e;bytes=b;}}
 private static final class Field{int tag,wire;long start,payload,length,end,number;}
 private static final class Node{String name="",op="";final List<String> inputs=new ArrayList<>(),outputs=new ArrayList<>();}
 private static final class Value{String name="";int type;final List<Object> shape=new ArrayList<>();}
 private static final class Writer{final FileOutputStream output;final LongConsumer progress;long written;Writer(FileOutputStream o,LongConsumer p){output=o;progress=p;}void write(byte[] bytes,int offset,int count)throws Exception {while(count>0){check();int n=Math.min(count,CHUNK);output.write(bytes,offset,n);written+=n;if(progress!=null)progress.accept(written);offset+=n;count-=n;}}}
 private static final class Memory{final byte[] bytes;int position;Memory(byte[] b){bytes=b;}long read()throws Exception {long value=0;for(int shift=0;shift<70;shift+=7){if(position>=bytes.length)throw new EOFException("Truncated model metadata");int b=bytes[position++]&255;if(shift==63&&(b&254)!=0)throw new IOException("Model metadata varint overflow");value|=(long)(b&127)<<shift;if((b&128)==0)return value;}throw new IOException("Model metadata varint overflow");}Field field()throws Exception {Field f=new Field();f.start=position;long key=read();if(key<=0||key>>>3>Integer.MAX_VALUE)throw new IOException("Invalid model metadata tag");f.tag=(int)(key>>>3);f.wire=(int)(key&7);if(f.wire==0){f.number=read();f.payload=position;f.end=position;}else if(f.wire==2){f.length=read();f.payload=position;if(f.length<0||f.length>bytes.length-position)throw new IOException("Invalid model metadata length");f.end=position+f.length;position=(int)f.end;}else if(f.wire==1||f.wire==5){f.payload=position;f.length=f.wire==1?8:4;f.end=position+f.length;if(f.end>bytes.length)throw new EOFException();position=(int)f.end;}else throw new IOException("Unsupported model metadata wire");return f;}}
}
